  function setModel(result,project,{refit=false}={}){restoreDetailVisibility();if(current)setAssemblyExploded(current.group,0);exploded=false;$('disciplineExplode').setAttribute('aria-pressed','false');$('disciplineMeasure').disabled=false;if(!renderer)init();clearMeasure();current=result;const keyView=project.domain+':'+(project.params.exteriorMode??'')+':'+(project.params.representation??'');if(visualKey!==keyView){$('disciplineGrid').checked=false;visualKey=keyView;}if(result.environmentImage&&skyImage!==result.environmentImage){skyEnvironment?.dispose();skyEnvironment=reflectionEnvironment(renderer,result.environmentImage);skyImage=result.environmentImage;}scene.environment=result.environmentImage?skyEnvironment.texture:environment.texture;scene.environmentIntensity=project.domain==='exterior'?(result.environmentImage?.85:.35):.85;scene.add(result.group);if(grid){grid.removeFromParent();grid.geometry.dispose();grid.material.dispose();}if(ground){ground.removeFromParent();ground.geometry.dispose();ground.material.dispose();}const size=Math.max(...result.size,.01);grid=new THREE.GridHelper(size*3,24,0x9baaba,0xdce3eb);grid.position.y=-size*.008;grid.visible=$('disciplineGrid').checked;scene.add(grid);ground=new THREE.Mesh(new THREE.PlaneGeometry(size*100,size*100),new THREE.MeshStandardMaterial({color:0xe8eae8,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=new THREE.Box3().setFromObject(result.group).min.y-size*.008;ground.receiveShadow=true;scene.add(ground);const key=scene.children.find(c=>c.isDirectionalLight&&c.castShadow);key.intensity=project.proposal?1.25:1.8;scene.children.find(c=>c.isHemisphereLight).intensity=project.proposal?.45:.7;key.position.set(-size*1.6,size*2.5,size*2);Object.assign(key.shadow.camera,{left:-size*1.2,right:size*1.2,top:size*1.2,bottom:-size*1.2,near:.001,far:size*12});key.shadow.camera.updateProjectionMatrix();key.shadow.normalBias=size*.0001;key.shadow.bias=-.0001;
    const assembly=result.group.userData.mechanicalAssembly;$('disciplineSourceView').hidden=!result.sourceProjection;$('disciplineExplode').hidden=!assembly;$('disciplineDetail').hidden=!inspectables().length;$('disciplineDetail').textContent=assembly?'⌕ Ver componente':'⌕ Ver detalle';$('assemblyComponents').hidden=!assembly;$('assemblyComponentButtons').replaceChildren();for(const part of result.group.children.filter(o=>o.userData.assemblyComponent)){const button=document.createElement('button');button.textContent=part.userData.label;button.onclick=()=>focusPart(part);$('assemblyComponentButtons').append(button);}$('disciplineTitle').textContent=project.domain==='exterior'?(result.sourceProjection?'El mismo proyecto, en 3D.':project.proposal?'Un edificio, en profundidad.':'La proyección, en relieve.'):project.domain==='structure'?'Ejes que toman forma.':'Del perfil a la pieza.';$('disciplineAssumptions').textContent=result.assumptions.join(' ');$('disciplineDesignStatus').textContent=result.sourceProjection?'Caras y materiales del Paso 2 · profundidad aproximada · sin redistribuir ventanas ni accesos':project.domain==='exterior'&&project.params.exteriorMode==='projection'?'Relieve de la proyección original · espesor provisional. El volumen del edificio requiere vistas adicionales.':assembly?'Conjunto por componentes · '+assembly.components.length+' grupos de sección'+(assembly.shaftEnabled?' · eje escalonado propuesto':' · núcleo conservado como vacío'):project.proposal?'Propuesta 3D · huecos y marcos con profundidad · laterales y fondo diseñados':project.section?'Corte longitudinal abierto · '+project.section.profiles.length+' regiones materiales · '+project.section.balls.length+' detalles circulares observados'+(result.group.userData.mechanicalDetails?.enabled?' · '+result.group.userData.mechanicalDetails.fasteners.length+' tornillos y '+result.group.userData.mechanicalDetails.bearings.length+' propuestas de rodamiento':''):project.hasDesign?'Acabados del Paso 2 · '+(project.designKind==='generated'?'Diseño generado con IA':'Presentación del proyecto')+' · revestimiento y vidrios vinculados':'Geometría del dibujo · revisa sus dimensiones antes de continuar';$('disciplineBadge').textContent=(project.calibration?(project.calibration.source==='cad-units'?'Unidades CAD declaradas':'Escala XY calibrada'):'Escala provisional')+' · Parámetros por revisar';$('disciplineSummary').textContent=`${result.parts} ${project.domain==='structure'?'barras':result.sourceProjection?'caras registradas':project.proposal||assembly?'componentes':'cuerpos'} · ${result.size.map(n=>(n*1000).toLocaleString('es-CL',{maximumFractionDigits:1})).join(' × ')} mm · ${project.domain==='mechanical'&&project.params.operation==='revolve'?(assembly?'Conjunto · componentes e interpretación revisables':project.section?'Corte longitudinal · material y vacíos observados':'Envolvente de revolución'):project.domain==='structure'?'Modelo de ejes y secciones':result.sourceProjection?'Modelo registrado al Paso 2':project.proposal?'Propuesta arquitectónica tridimensional':'Extrusión de perfiles'}`;applyDisplay();if(refit||!controls.target.lengthSq())fit(result.sourceProjection?'source':lastView);else resize();}
  function applyDisplay(){needsRender=true;if(!current)return;const box=new THREE.Box3().setFromObject(current.group),center=box.getCenter(new THREE.Vector3()),cut=$('disciplineCut').checked?new THREE.Plane(new THREE.Vector3(0,0,-1),center.z):null;current.group.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){m.wireframe=$('disciplineWire').checked;m.clippingPlanes=cut?[cut]:[];m.clipShadows=true;m.needsUpdate=true;}});if(grid)grid.visible=$('disciplineGrid').checked;}
  function pick(event){needsRender=true;if(!measure||!current||event.button!==0)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1),camera);const hits=ray.intersectObject(current.group,true).filter(h=>h.object.visible!==false&&!h.object.userData.annotation&&(!$('disciplineCut').checked||h.point.z<=new THREE.Box3().setFromObject(current.group).getCenter(new THREE.Vector3()).z));if(!hits.length)return;if(measurePoints.length===2)clearMeasure();const point=hits[0].point;measurePoints.push(point.clone());const radius=Math.max(...current.size)*.008,marker=new THREE.Mesh(new THREE.SphereGeometry(radius,12,8),new THREE.MeshBasicMaterial({color:0xe18b35,depthTest:false}));marker.position.copy(point);marker.renderOrder=100;scene.add(marker);markers.push(marker);if(measurePoints.length===2){line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(measurePoints),new THREE.LineBasicMaterial({color:0x0073bf,depthTest:false}));scene.add(line);$('disciplineDistance').textContent=`${(measurePoints[0].distanceTo(measurePoints[1])*1000).toLocaleString('es-CL',{maximumFractionDigits:2})} mm · Distancia entre superficies del modelo${current.assumptions.some(a=>a.startsWith('Escala provisional'))?' · Provisional':''}`;}else $('disciplineDistance').textContent='Primer punto sobre superficie · marca el segundo';}
