    current.group.traverse(object=>{if(!object.isMesh&&!object.isLine)return;let ancestor=object;while(ancestor&&ancestor!==selected)ancestor=ancestor.parent;const observed=object.userData.observedCircularFeature&&selected.userData.observedSourceCenters?.some(p=>p.every((n,i)=>n===object.userData.sourceCenter?.[i]));detailVisibility.set(object,object.visible);object.visible=!!ancestor||!!observed;});
    const box=new THREE.Box3().setFromObject(selected),center=box.getCenter(new THREE.Vector3()),radius=box.getSize(new THREE.Vector3()).length(),direction=new THREE.Vector3(selected.name==='proposed-threaded-fastener'?-1:1,.45,1.4).normalize();
